package mx.uv.dsw.telemetry; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; @SpringBootTest @AutoConfigureMockMvc class TelemetryControllerTest {@Autowired MockMvc mvc;@Test void rechazaPeticionSinClave()throws Exception{mvc.perform(post("/api/telemetry").contentType(MediaType.APPLICATION_JSON).content("{\"deviceId\":\"sensor-01\",\"value\":24.5}")).andExpect(status().isUnauthorized());}@Test void rechazaValorFueraDeRango()throws Exception{mvc.perform(post("/api/telemetry").header("X-Lab-Key","lab-only-key").contentType(MediaType.APPLICATION_JSON).content("{\"deviceId\":\"sensor-01\",\"value\":999}" )).andExpect(status().isBadRequest());}@Test void creaTelemetriaAutorizada() throws Exception {mvc.perform(post("/api/telemetry").header("X-Lab-Key","lab-only-key").contentType(MediaType.APPLICATION_JSON).content("{\"deviceId\":\"sensor-01\",\"value\":24.5}" )).andExpect(status().isCreated()).andExpect(jsonPath("$.deviceId").value("sensor-01"));}}
